script.text:
			
function active$VoucherFilter$(sender) {sender.add_onResponseComplete(on$Filter$ResponseComplete);}
function close$VoucherFilter$(sender) {try {sender.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}}
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var k = new Array();
			var g = f.grid, g._tu_ngay = f.getItemValue('tu_ngay'), g._den_ngay = f.getItemValue('den_ngay'); 
			if(g._tu_ngay != null) Array.add(k, {Name: 'tu_ngay', Opr: '>=', Value: g._tu_ngay, Type: 'DateTime', Ignore: false});			if(g._den_ngay != null) Array.add(k, {Name: 'den_ngay', Opr: '>=', Value: g._den_ngay, Type: 'DateTime', Ignore: false});
			g.set_externalKey(k);
			g._alterTitle = [null, [['%s', '', true]]];
			break;
		default:
			break;
	}
}
